// Generate one simulated pump sensor reading.
// rand() returns a value in [min, max] rounded to 1 decimal place.
function rand(min, max) {
    return Math.round((Math.random() * (max - min) + min) * 10) / 10;
}

const STATUSES = ['RUNNING', 'STOPPED', 'FAULT'];

msg.payload = {
    flowRate:          rand(50, 300),   // litres/minute
    rpm:               rand(1000, 3600), // revolutions/minute
    vibration:         rand(0.5, 12),   // mm/s
    suctionPressure:   rand(0.5, 3),    // bar
    dischargePressure: rand(2, 12),     // bar
    motorTemp:         rand(20, 90),    // degrees Celsius
    status:            STATUSES[Math.floor(Math.random() * STATUSES.length)],
    timestamp:         new Date().toISOString()
};

// Tell the backend the body is JSON so Express parses it correctly.
msg.headers = { "Content-Type": "application/json" };

return msg;
